    def prepare_left_ad_hoc_host(self, scenario: RequestScenario) -> None:
        """Record a solo host's attendance and departure before reusing the join endpoint."""
        self.prepare_call()
        room = ConferenceRoom.objects.create(
            title="Host rejoining", created_by=self.normal_user
        )
        controller = ConferenceController(self.normal_user)
        self.session = controller.start(
            room, [self.normal_user], "video", "host-rejoining"
        )
        self.original_session_id = self.session.pk
        self.original_share_token = self.session.share_token
        self.previous_identity = controller.join(self.session.pk)["identity"]
        reconcile_event(
            self.connection_event(
                "EV_host_joined", "participant_joined", self.previous_identity
            )
        )
        reconcile_event(
            self.connection_event(
                "EV_host_left", "participant_left", self.previous_identity, offset=1
            )
        )
        scenario.view_kwargs = {"session_id": self.original_session_id}

    def rejoined_host_credentials(self, response: HttpResponse) -> bool:
        """Keep the meeting code and host authority while issuing a fresh connection identity."""
        self.session.refresh_from_db()
        data = response.json()
        return (
            data["session_id"] == str(self.original_session_id)
            and self.session.share_token == self.original_share_token
            and self.session.status == "active"
            and data["can_end"] == "true"
            and data["identity"] != self.previous_identity
            and bool(data["token"])
            and self.create_room.await_count == 1
            and ConferenceAttendance.objects.filter(left_at__isnull=False).count() == 1
            and not ConferenceAttendance.objects.filter(left_at__isnull=True).exists()
        )

    def prepare_late_calendar_host(self, scenario: RequestScenario) -> None:
        """Reserve an unstarted meeting whose scheduled start was two minutes ago."""
        self.prepare_call()
        start = timezone.now() - timedelta(minutes=2)
        event = CalendarEvent.objects.create(
            title="Late host arrival",
            organizer_email="host@example.com",
            start=start,
            end=start + timedelta(hours=1),
            event_timezone="UTC",
        )
        reserve_calendar_conference(event, self.normal_user, [], "https://testserver/")
        self.session = event.conference_session
        scenario.view_kwargs = {"session_id": self.session.pk}

    def late_host_credentials(self, response: HttpResponse) -> bool:
        """Verify a late host can provision and join without creating attendance prematurely."""
        self.session.refresh_from_db()
        data = response.json()
        return (
            data["session_id"] == str(self.session.pk)
            and data["can_end"] == "true"
            and data["driver"] == "livekit"
            and bool(data["token"])
            and self.session.status == "ringing"
            and self.create_room.await_count == 1
            and not ConferenceAttendance.objects.exists()
        )

    def valid_credentials(self, response: HttpResponse) -> bool:
        """Verify the real token and ensure credential issuance is not counted as attendance."""
        data = json.loads(response.content)
        claims = jwt.decode(
            data["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return (
            claims["video"]["room"] == self.session.livekit_room_name
            and claims["sub"] == data["identity"]
            and data["driver"] == "livekit"
            and data["can_video"] == "true"
            and data["can_screen_share"] == "true"
            and "screen_share" in claims["video"]["canPublishSources"]
            and data["can_end"] == "false"
            and len(data["identity"]) <= 255
            and not ConferenceAttendance.objects.exists()
            and response["Cache-Control"] == "private, no-store"
        )

    def prepare_provider_identity(self, scenario: RequestScenario) -> None:
        """Provide an IM presentation override after creating an authorized session."""
        self.prepare_session(scenario)
        self.enterContext(
            patch(
                "bloomerp.communication.builtins.instant_messaging.definition.IMProviderDefinition.resolve_identity",
                return_value={
                    "displayName": "Chat Identity",
                    "avatar": "/media/chat-avatar.png",
                    "address": "private@example.test",
                },
            )
        )

    def provider_identity(self, response: HttpResponse) -> bool:
        """Verify names and avatars match IM while metadata contains no contact address."""
        claims = jwt.decode(
            json.loads(response.content)["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return (
            claims["name"] == "Chat Identity"
            and json.loads(claims["metadata"])
            == {
                "displayName": "Chat Identity",
                "avatar": "/media/chat-avatar.png",
                "initials": "CI",
            }
            and claims["video"]["canUpdateOwnMetadata"] is False
        )

    def prepare_no_screen(self, scenario: RequestScenario) -> None:
        """Resolve camera access independently from screen sharing after admission."""
        self.prepare_session(scenario)
        self.screen_capability_patch = patch(
            "bloomerp.communication.builtins.instant_messaging.calling.call_capabilities",
            return_value=IMCallCapabilities(audio=True, video=True),
        )
        self.screen_capability_patch.start()
        self.addCleanup(self.screen_capability_patch.stop)

    def restore_screen_capabilities(self, scenario: RequestScenario) -> None:
        """Remove the capability override before the next declarative scenario."""
        self.screen_capability_patch.stop()

    def no_screen_credentials(self, response: HttpResponse) -> bool:
        """Verify the UI capability and signed grants both deny screen publication."""
        data = json.loads(response.content)
        claims = jwt.decode(
            data["token"],
            "instance-secret-at-least-32-characters",
            algorithms=["HS256"],
        )
        return data["can_screen_share"] == "false" and set(
            claims["video"]["canPublishSources"]
        ) == {"microphone", "camera"}
